      LT.forEach((t, i) => { g += `<rect x="${LX - 70}" y="${LY[i] - 20}" width="130" height="40" rx="20" fill="${I.ink}"/><text x="${LX - 5}" y="${LY[i] + 5}" text-anchor="middle" font-size="14" font-weight="600" fill="${I.bg}">${t}</text>`; });
      RT.forEach((t, i) => { g += `<rect x="${RX - 80}" y="${RY[i] - 18}" width="150" height="36" rx="18" fill="${I.surf}" stroke="${I.line}"/><text x="${RX - 5}" y="${RY[i] + 5}" text-anchor="middle" font-size="14" fill="${I.ink}">${t}</text>`; });
