      + R.map(([n, p, pt, free, cells], i) => `<div style="display:grid;grid-template-columns:${gt};gap:0 16px;align-items:center;padding:16px 18px;border-radius:12px;${i ? `box-shadow:inset 0 -1px 0 ${I.faint}` : `background:${mix(I.surf, I.data, I.dark ? .14 : .06)};box-shadow:inset 0 0 0 1.5px ${I.data};margin-bottom:6px`}"><div><div style="font:600 15px ${SANS};color:${I.ink}">${n}</div><div style="font:400 12px ${SANS};color:${I.mute};margin-top:3px">Free: ${free}</div></div><div><div style="display:flex;gap:10px;align-items:center"><div style="height:10px;width:${p / 1.5 * 100}%;border-radius:5px;background:${i ? mix(I.ink, I.bg, .55) : I.data}"></div><span style="font:600 13px ${GMONO};color:${I.ink}">$${p.toFixed(2)}</span></div><div style="font:400 12px ${SANS};color:${I.mute};margin-top:5px">${pt}</div></div>${cells.map((v, j) => `<div style="display:grid;justify-items:center;gap:5px;text-align:center"><span style="display:grid;place-items:center;height:16px">${mark(v, j)}</span><span style="font:400 11px ${SANS};color:${I.mute}">${v}</span></div>`).join('')}</div>`).join('')
