    const ta = document.createElement('textarea'); ta.value = REAL; ta.rows = 9; ta.spellcheck = false; ta.style.cssText = `width:100%;box-sizing:border-box;padding:14px;border:0;border-radius:12px;background:#0d0d0d;color:#d4d4d4;font:400 12px/1.65 ${GMONO};resize:none;box-shadow:inset 0 0 0 1px ${I.dark ? '#2a2a2a' : '#0d0d0d'}`;
    const res = H('display:grid;gap:10px'); let timer = 0;
