    g.appendChild(H('display:none', '<style>@keyframes cvspin{to{transform:rotate(360deg)}}</style>')); run();
    return B().block(s, I, { eyebrow: 'Verify us', tone: 'pub', title: 'Don’t trust the user agent. Check the signature.', cards: [['Web Bot Auth', 'Every request is signed. Our key directory is public.'], ['IP ranges', 'Published and updated as a JSON file.'], ['Reverse DNS', 'Every agent IP resolves to a host under iframely.com.'], ['Self-check', 'Paste a request’s headers and we tell you whether it was us.']] }, { el: g, text: REAL });
